(function () {
  'use strict';
  globalThis.MediaInfoWorkspace = function (api) {
    const C=globalThis.MediaInfoProjectsCore,L=globalThis.MediaInfoLearning,e=C.escape,projects=globalThis.MediaInfoProjects.projects;
    const media=()=>globalThis.MediaInfoProjectMedia||{},$=s=>document.querySelector(s),rfor=api.rfor;
    let preview=false,focus=null,focusError=false,pendingTemplate=null,undoStudio=null,pendingImage=null;
    const asset=file=>'assets/projects/media/'+file+'?v=3';
    const videoTime=seconds=>{const t=Math.max(0,Math.floor(seconds));return `${Math.floor(t/60)}:${String(t%60).padStart(2,'0')}`;};
    const action=(name,p,label,primary=false,extra='')=>`<button type="button" class="p-button${primary?' primary':''}" data-action="${name}" data-project="${p.id}" ${extra}>${label}</button>`;
    const field=(id,label,value,attrs='',type='text')=>`<label class="workspace-field" for="${id}"><span>${label}</span><input id="${id}" type="${type}" value="${e(value)}" ${attrs}></label>`;
    function figure(p,i=1,small=false){const s=media()[p.id]?.chapters[i];return s?`<figure class="learning-figure${small?' compact':''}"><button type="button" data-action="enlarge-example" data-project="${p.id}" data-scene="${i}" aria-label="Grafik vergrössern: ${e(s.title)}"><img src="${asset(s.image)}" alt="${e(s.title+'. '+s.why)}" width="1280" height="720" loading="lazy"><span>Grafik vergrössern ⤢</span></button>${small?'':`<figcaption>${e(s.why)}</figcaption>`}</figure>`:'';}
    function video(p){const m=media()[p.id];if(!m)return '';return `<div class="example-video"><video id="projectVideo" controls playsinline preload="none" poster="${asset(p.id+'-poster.jpg')}" aria-label="Beispielvideo: ${e(p.title)}" aria-describedby="videoDescription"><source src="${asset(p.id+'.mp4')}" type="video/mp4"><track kind="captions" src="${asset(p.id+'.vtt')}" srclang="de" label="Deutsch – gesprochener Kommentar">Ihr Browser kann das Video nicht abspielen. Nutzen Sie den Download oder die Bildfolge darunter.</video><p id="videoDescription" class="note-hint">${videoTime(m.duration)} Minuten · mit KI-generierter Sprecherinnenstimme. Die Sprecherin erklärt Entscheidungen und gibt Tipps für Ihren eigenen Versuch. Untertitel können Sie im Player zuschalten. Pausieren Sie zum genauen Betrachten; den vollständigen Kommentar finden Sie auch in der Bildfolge.</p><div class="video-chapters" aria-label="Zu einem Videokapitel springen">${m.chapters.map((s,i)=>`<button type="button" data-action="video-chapter" data-project="${p.id}" data-scene="${i}"><span>${videoTime(s.start)}</span>${e(s.title)}</button>`).join('')}</div><div class="p-actions"><a class="project-link" href="${asset(p.id+'.mp4')}" download>Video mit Ton herunterladen ↓</a><a class="project-link" href="${asset(p.id+'-sprechtext.txt')}" download>Sprechtext herunterladen ↓</a></div></div>`;}
    function mediaView(p){const m=media()[p.id];return `<section class="content-panel"><p class="eyebrow">Ansehen · verstehen · selbst anwenden</p><h2 id="viewTitle" tabindex="-1">So kann ein gutes Ergebnis aussehen</h2><p>${e(m?.tag||p.title)}. Achten Sie darauf, <strong>warum</strong> ein Beispiel funktioniert. Übertragen Sie die Idee auf Ihr eigenes Produkt.</p>${video(p)}</section><section class="content-panel"><h2>Die Bildfolge zum Nachlesen</h2><p>Öffnen Sie nur das Beispiel, das Ihnen gerade weiterhilft. Zu jeder Grafik finden Sie den vollständigen gesprochenen Kommentar. Die Darstellungen sind eigens erstellte Beispielaufbauten.</p>${(m?.chapters||[]).map((s,i)=>`<details class="visual-detail" ${i===1?'open':''}><summary>${e(s.title)}</summary>${figure(p,i)}<p>${e(s.caption)}</p><div class="spoken-commentary"><h3>Die Sprecherin erklärt</h3>${(s.narration||[]).map(t=>`<p>${e(t)}</p>`).join('')}</div></details>`).join('')}<div class="p-actions"><a class="p-button primary" href="#${p.id}/werkbank">Mit einer Vorlage selbst beginnen →</a><a class="p-button" href="#${p.id}/cockpit">Meine Lektion planen</a></div></section>`;}
    function summary(p,record=rfor(p)){
      const q=L.plan(p,record),running=record.planner.session.status==='running',paused=record.planner.session.status==='paused';
      return `<div class="assistant-summary"><span class="assistant-mark" aria-hidden="true">✦</span><div><strong>${q.stale?'Eine frühere Lektion ist noch geöffnet':running?q.left<=q.reserve?'Jetzt ist Zeit zum Sichern':`Noch ${q.left} Minuten in Ihrem Zeitfenster`:paused?'Ihre Arbeitszeit ist pausiert':'Ihr Projekt-Assistent'}</strong><p>${q.stale?'Beenden Sie den alten Eintrag im Cockpit und planen Sie Ihre neue Lektion.':running&&q.left<=q.reserve?'Produkt speichern, nächsten Schritt festhalten und Projektsicherung herunterladen.':!running&&!paused&&record.planner.nextAction?`Ihr gemerkter Einstieg: ${e(record.planner.nextAction)}`:`${record.checks.length} von ${p.steps.length} Schritten geprüft. ${record.finishedAt?'Der Basisauftrag ist abgeschlossen.':'Als Nächstes: '+e(p.steps.find((_,i)=>!record.checks.includes(i))?.title||'Qualitätskontrolle')+'.'}`}</p></div><a class="p-button" href="#${p.id}/cockpit">Cockpit öffnen</a></div>`;
    }
    function courseFocus(){
      const names={onenote:'OneNote',digipen:'DigiPen',scan:'Scannen'},files={onenote:'onenote',digipen:'digipen',scan:'scannen'},keys={onenote:'onenoteWorkshopGS1_student_v3',digipen:'digitalArbeiten_digipen_v1',scan:'digitalArbeiten_scannen_v1'};
      if(!focus?.active)return `<p>${focusError?'Der aktuelle Klassenfokus konnte gerade nicht geladen werden. ':''}<a href="index.html#start" target="_blank" rel="noopener">Heutige Aufträge auf der Startseite prüfen ↗</a>. Entscheiden Sie danach unten, ob noch Pflichtarbeit ansteht oder Herr Marti den Projektstart freigegeben hat.</p>`;
      return `<p><strong>${e(focus.title||'Heute wichtig')}</strong> ${e(focus.message||'')}</p><ul class="focus-tasks">${(focus.tasks||[]).filter(t=>files[t.track]&&Number.isInteger(t.taskId)&&t.taskId>0&&t.taskId<13).map(t=>{let raw={};try{raw=JSON.parse(localStorage.getItem(keys[t.track])||'{}')}catch{}const ids=t.track==='onenote'?raw.doneTasks:raw.done,done=Array.isArray(ids)&&ids.map(Number).includes(t.taskId);return `<li><a href="${files[t.track]}.html#auftrag-${t.taskId}" target="_blank" rel="noopener">${e(names[t.track])} · Auftrag ${t.taskId} ↗</a><span>${done?'✓ Im Workshop erledigt':'Noch offen'}</span></li>`;}).join('')}</ul><p class="note-hint">Berücksichtigen Sie zusätzlich Aufträge, die Herr Marti direkt im Unterricht nennt.</p>`;
    }
    async function loadFocus(){const owner=api.owner();focus=null;focusError=false;if(!owner||typeof fetch!=='function')return;try{const response=await fetch('/api/today?email='+encodeURIComponent(owner),{cache:'no-store'});if(!response.ok)throw new Error('offline');const data=await response.json();if(api.owner()!==owner)return;focus=data.focus||null;}catch{if(api.owner()!==owner)return;focusError=true;}const el=$('#courseFocus');if(el)el.innerHTML=courseFocus();}
    function schedule(p){const r=rfor(p),q=L.plan(p,r),pl=r.planner;
      const next=q.today.at(-1),nextTitle=next?.partial?`Schritt ${next.index+1} weiterführen`:p.steps.find((_,i)=>!r.checks.includes(i)&&!q.today.some(x=>x.index===i))?.title||'Qualitätskontrolle oder Vertiefung';
      return `<div class="plan-stats"><div><strong>${q.left}</strong><span>Minuten verfügbar</span></div><div><strong>${q.work}</strong><span>Minuten am Projekt</span></div><div><strong>${q.reserve}</strong><span>Minuten fürs Sichern</span></div></div>${q.stale?'<p class="finish-hint">Diese Lektion wurde vor mehr als vier Stunden gestartet. Beenden Sie den alten Eintrag; die Uhr bildet Ihre tatsächliche Arbeitszeit jetzt nicht mehr verlässlich ab.</p>':''}<ol class="lesson-timeline">${q.mandatory?`<li class="lesson-required"><span class="timeline-time">${q.mandatory} Min.</span><div><strong>Zuerst: offene Pflichtaufträge</strong><p>Wechseln Sie zu den heutigen Aufträgen. Falls Sie länger brauchen, passen Sie die Zeit an – die Projektarbeit wartet.</p><a href="index.html#start" target="_blank" rel="noopener">Aufträge öffnen ↗</a> ${action('mandatory-done',p,'Pflichtarbeit für heute erledigt')}</div></li>`:''}${q.today.map(s=>`<li><span class="timeline-time">${s.minutes} Min.</span><div><strong>${s.index<6?`Schritt ${s.index+1}: `:''}${e(s.title)}${s.partial?' · beginnen':''}</strong><p>${s.partial?'Arbeiten Sie so weit, wie Sie kommen. Notieren Sie den erreichten Stand; der Schritt bleibt bis zum Ergebnischeck offen.':s.index<6?e(p.steps[s.index].goal):'Öffnen Sie Ihr Produkt und prüfen Sie jedes Kriterium daran.'}</p><a href="#${p.id}/${s.index<6?'schritt-'+(s.index+1):'abschluss'}">${s.partial?'Diesen Abschnitt beginnen':'Auftrag öffnen'} →</a></div></li>`).join('')}${q.reserve?`<li class="lesson-save"><span class="timeline-time">${q.reserve} Min.</span><div><strong>Sichern und den nächsten Einstieg vorbereiten</strong><p>Produkt speichern, Speicherort und nächsten Handgriff festhalten, Projektsicherung herunterladen.</p>${action('lesson-close',p,'Lektion abschliessen')}</div></li>`:''}</ol>${q.mandatoryOverflow?`<p class="finish-hint">Ihre geschätzte Pflichtarbeit passt nicht vollständig in diese Lektion: etwa ${q.mandatoryOverflow} Minuten bleiben zusätzlich für später offen. Besprechen Sie den Zeitplan bei Bedarf mit Herrn Marti.</p>`:''}${!q.work?`<p class="finish-hint">${r.finishedAt?'Ihr Basisauftrag ist fertig. Sie können eine Vertiefung planen oder ein weiteres Projekt auswählen.':'Für neue Projektarbeit bleibt in diesem Zeitfenster kaum Raum. Schliessen Sie Ihre aktuelle Arbeit sauber ab und planen Sie den Einstieg für die nächste Lektion.'}</p>`:''}${q.free>0&&!r.finishedAt?`<p class="note-hint">${q.free} Minuten bleiben als Puffer. Prüfen und verbessern Sie Ihr Ergebnis; der Abschluss wird nicht automatisch gesetzt.</p>`:''}<div class="next-lesson"><p class="eyebrow">Danach im Gesamtplan</p><h3>${q.later?`Noch etwa ${q.later} Minuten Projektarbeit`:'Der Basisauftrag passt voraussichtlich in diese Etappe'}</h3><p>${q.later?`Wenn die heutige Etappe gelingt: nächstes Mal ${e(nextTitle)}. Dafür sind bei ${pl.nextMinutes} Minuten pro Lektion ungefähr ${q.nextSessions} weitere ${q.nextSessions===1?'Etappe':'Etappen'} nötig.`:'Zum Abschluss gehören immer der Test am Produkt und das Sichern. Wenn etwas länger dauert, übernimmt das Cockpit die offenen Schritte in die Folgelektion.'}</p><p class="note-hint">Richtwerte für die Planung. Ein Schritt zählt erst als erledigt, wenn Sie sein Ergebnis geprüft haben. Neue Pflichtaufträge in der Folgelektion planen Sie dann zuerst ein.</p></div>`;
    }
    function plannerView(p){const r=rfor(p),pl=r.planner,s=pl.session,active=['running','paused'].includes(s.status),nextIndex=p.steps.findIndex((_,i)=>!r.checks.includes(i));
      return `<section class="content-panel cockpit-panel"><p class="eyebrow">Ihr Cockpit · eine Lektion nach der anderen</p><h2 id="viewTitle" tabindex="-1">Was ist heute realistisch?</h2><p>Planen Sie mit der Zeit, die <strong>ab jetzt</strong> zur Verfügung steht. Das Cockpit reserviert den Schluss zum Sichern und zeigt, was in der Folgelektion weitergeht.</p><div class="course-focus"><h3>1 · Heutige Aufträge einbeziehen</h3><div id="courseFocus">${courseFocus()}</div><label class="workspace-field" for="plan-readiness"><span>Mein Stand bei den Pflichtaufträgen</span><select id="plan-readiness" data-plan="readiness" data-project="${p.id}"><option value="unset" ${pl.readiness==='unset'?'selected':''}>Bitte bewusst auswählen</option><option value="done" ${pl.readiness==='done'?'selected':''}>Meine aktuellen Pflichtaufträge sind erledigt</option><option value="open" ${pl.readiness==='open'?'selected':''}>Ich muss noch Pflichtaufträge erledigen</option><option value="released" ${pl.readiness==='released'?'selected':''}>Herr Marti hat meinen Projektstart freigegeben</option></select></label></div><h3>2 · Zeitrahmen festlegen</h3><div class="planner-fields">${field('plan-minutes',active?'Gesamtes Zeitfenster dieser Lektion (Min.)':'Verbleibende Zeit ab jetzt (Minuten)',pl.minutes,`min="1" max="180" step="1" data-plan="minutes" data-project="${p.id}"`,'number')}${pl.readiness==='open'?field('plan-mandatory','Davon noch für Pflichtarbeit (Minuten)',pl.mandatory,`min="0" max="180" step="5" data-plan="mandatory" data-project="${p.id}"`,'number'):''}${field('plan-nextMinutes','Zeit in der Folgelektion (Minuten)',pl.nextMinutes,`min="10" max="180" step="5" data-plan="nextMinutes" data-project="${p.id}"`,'number')}${field('plan-nextDate','Folgelektion am (freiwillig)',pl.nextDate,`data-plan="nextDate" data-project="${p.id}"`,'date')}</div>${nextIndex>=0?`<details class="plan-adjust"><summary>Am aktuellen Schritt schon teilweise gearbeitet?</summary><p>Schätzen Sie, wie viele Minuten Sie für «${e(p.steps[nextIndex].title)}» noch brauchen. So berücksichtigt der Plan auch angefangene Arbeit.</p>${field('plan-remaining','Geschätzte Restzeit dieses Schritts (Minuten)',pl.remaining[nextIndex]??L.estimate(p.steps[nextIndex]),`min="1" max="90" data-remaining="${nextIndex}" data-project="${p.id}"`,'number')}</details>`:''}<div class="p-actions">${s.status==='running'?action('lesson-pause',p,'Zeitmessung pausieren'):s.status==='paused'?action('lesson-resume',p,'Zeitmessung fortsetzen',true):action('lesson-start',p,s.status==='closed'?'Neue Lektion mit diesem Plan starten':'Lektion mit diesem Plan starten',true)}${active?action('lesson-close',p,'Für heute abschliessen'):''}</div><p class="note-hint">Die Uhr startet erst mit dem Knopf. Sie läuft auch weiter, wenn Sie in OneNote oder einem anderen Tab arbeiten. Eine Pause stoppt sie. Es wird nichts automatisch als erledigt markiert.</p></section><section class="content-panel"><p class="eyebrow">3 · Ihr konkreter Etappenplan</p><h2>Heute und nächstes Mal</h2><div id="lessonSchedule">${schedule(p)}</div></section>${pl.nextAction||pl.file?`<section class="content-panel handoff-card"><p class="eyebrow">Ihr letzter gemerkter Arbeitsstand</p><h2>Hier wieder einsteigen</h2><p><strong>Nächster Handgriff:</strong> ${e(pl.nextAction||'Im ersten offenen Schritt weiterarbeiten.')}</p><p><strong>Speicherort:</strong> ${e(pl.file||'Noch nicht festgehalten.')}</p>${pl.nextDate?`<p><strong>Geplante Folgelektion:</strong> ${e(pl.nextDate.split('-').reverse().join('.'))}</p>`:''}<a class="p-button primary" href="#${p.id}/${C.next(r,p)}">Zum offenen Auftrag →</a></section>`:''}${pl.history.length?`<details class="content-panel"><summary>Meine letzten ${pl.history.length} Arbeitsetappen</summary><ol class="session-history">${pl.history.slice().reverse().map(h=>`<li><strong>${e(h.endedAt.slice(0,10).split('-').reverse().join('.'))}</strong> · ca. ${h.minutes} Min. · ${h.steps} neu geprüfte Schritte<p>${e(h.note)}</p></li>`).join('')}</ol></details>`:''}`;
    }
    function productPreview(p,s=rfor(p).studio){const cfg=L.setups[p.id];return `<article class="product-preview product-${p.id}"><header><p class="eyebrow">${e(cfg.noun)} · meine Fassung</p><h2>${e(s.title||'Mein Projekttitel')}</h2>${s.intro?`<p class="product-intro">${e(s.intro)}</p>`:''}</header><div class="product-blocks">${s.blocks.map((b,i)=>`<section class="product-block"><span class="product-index">${i+1}</span><h3>${e(b.title||'Eigener Abschnitt')}</h3>${b.text?`<p>${e(b.text)}</p>`:'<p class="empty-prompt">Hier fehlt noch Ihr eigener Inhalt.</p>'}${b.image?`<figure><img src="${b.image}" alt="${e(b.caption||b.title||'Eigene Abbildung')}">${b.caption?`<figcaption>${e(b.caption)}</figcaption>`:''}</figure>`:''}${b.extra?`<div class="product-evidence"><strong>${e(cfg.extra)}</strong><p>${e(b.extra)}</p></div>`:''}</section>`).join('')}</div>${s.reflection?`<section class="product-reflection"><h3>Test und Verbesserung</h3><p>${e(s.reflection)}</p></section>`:''}</article>`;}
    function templates(p){const cfg=L.setups[p.id];return `<div class="template-grid">${cfg.templates.map((t,i)=>`<article class="template-card"><span class="template-symbol" aria-hidden="true">${i===2?'＋':i===0?'▦':'▤'}</span><h3>${e(t.name)}</h3><p>${e(t.description)}</p><small>${t.titles.length} bearbeitbare Bereiche · eigene Bilder möglich</small>${action('template-preview',p,'Vorlage ansehen',false,`data-template="${t.id}"`)}</article>`).join('')}</div>`;}
    function studioView(p){const r=rfor(p),s=r.studio,cfg=L.setups[p.id],exists=L.hasWork(s);
      return `<section class="content-panel"><p class="eyebrow">Ihre Werkbank · direkt hier arbeiten</p><h2 id="viewTitle" tabindex="-1">${exists?'Ihre eigene Fassung wächst hier':'Vorlage wählen. Mit eigenen Inhalten füllen.'}</h2><p>${p.id==='dokumente'?'Hier entsteht Ihr Dossier-Plan mit Qualitätsnachweis. Die eigentliche dreiseitige PDF erstellen Sie im Scan- oder Bildweg.':p.id==='cockpit'?'Entwerfen Sie hier die Inhalte. Übertragen Sie sie dann nach OneNote, setzen Sie dort funktionierende Links und Aufgaben-Kästchen und machen Sie den Alltagstest.':'Hier können Sie Ihr Produkt entwerfen, eigene Bilder einfügen und Ihre Fassung als PDF drucken oder in Ihr Arbeitsprogramm kopieren.'}</p>${p.id==='tutorial'&&r.choice==='video'?'<p class="finish-hint">Sie haben den Videoweg gewählt. Nutzen Sie die Werkbank als Drehplan. Die eigene Aufnahme erstellen und speichern Sie in Ihrem Aufnahmeprogramm.</p>':''}${exists?`<details class="template-switch"><summary>Eine andere Vorlage ansehen</summary><p>Eine neue Vorlage wird erst nach Ihrer ausdrücklichen Auswahl übernommen. Sichern Sie eine vorhandene Fassung vor dem Ersetzen.</p>${templates(p)}</details>`:templates(p)}</section>${exists?`<section class="content-panel studio-editor"><div class="studio-toolbar"><div><strong>${preview?'Ergebnisansicht':'Bearbeiten'}</strong><p class="note-hint">Ihre Eingaben werden beim Tippen lokal gespeichert. Änderungen setzen einen bereits gesetzten Qualitätscheck zurück.</p></div><div class="p-actions">${action('studio-toggle',p,preview?'Weiter bearbeiten':'Vorschau ansehen',true)}${action('backup',p,'Bearbeitbare Sicherung')}</div></div>${preview?productPreview(p):`<div class="studio-fields">${field('studio-title','Titel Ihrer Fassung',s.title,`maxlength="160" data-studio="title" data-project="${p.id}"`)}<label class="workspace-field" for="studio-intro"><span>${e(cfg.intro)}</span><textarea id="studio-intro" data-studio="intro" data-project="${p.id}" maxlength="2000" rows="3">${e(s.intro)}</textarea></label></div><p class="studio-guidance">${e(cfg.hint)}</p><div class="studio-blocks">${s.blocks.map((b,i)=>`<details class="studio-block" open><summary><span class="step-number">${i+1}</span> <span id="block-label-${i}">${e(b.title||'Eigener Abschnitt')}</span></summary><div class="studio-block-body">${field('block-title-'+i,'Titel dieses Bereichs',b.title,`maxlength="160" data-studio="title" data-block="${i}" data-project="${p.id}"`)}<label class="workspace-field" for="block-text-${i}"><span>${e(cfg.body)}</span><textarea id="block-text-${i}" data-studio="text" data-block="${i}" data-project="${p.id}" maxlength="6000" rows="4" placeholder="Ihre eigenen Sätze …">${e(b.text)}</textarea></label><label class="workspace-field" for="block-extra-${i}"><span>${e(cfg.extra)}</span><textarea id="block-extra-${i}" data-studio="extra" data-block="${i}" data-project="${p.id}" maxlength="3000" rows="3" placeholder="Ein konkreter Test, Beleg oder erwarteter Zwischenstand …">${e(b.extra)}</textarea></label><div class="image-slot">${b.image?`<img src="${b.image}" alt="${e(b.caption||'Ihr eigenes Bild')}" loading="lazy">`: '<p>Platz für Ihren eigenen Screenshot, Ihre Skizze oder ein Vorher-Nachher-Bild.</p>'}${action('studio-image',p,b.image?'Bild ersetzen':'Eigenes Bild einfügen',false,`data-block="${i}"`)}${b.image?action('studio-image-remove',p,'Bild entfernen',false,`data-block="${i}"`):''}${field('block-caption-'+i,'Bildbeschreibung: Was soll man erkennen?',b.caption,`maxlength="300" data-studio="caption" data-block="${i}" data-project="${p.id}"`)}<p class="note-hint">PNG, JPG oder WebP, maximal 8 MB. Bilder werden für die Vorlage verkleinert. Alternativ Screenshot kopieren und in ein Textfeld dieses Bereichs einfügen.</p></div><div class="block-tools">${action('studio-up',p,'↑ Nach oben',false,`data-block="${i}" ${i===0?'disabled':''}`)}${action('studio-down',p,'↓ Nach unten',false,`data-block="${i}" ${i===s.blocks.length-1?'disabled':''}`)}${action('studio-remove',p,'Bereich entfernen',false,`data-block="${i}"`)}</div></div></details>`).join('')}</div>${action('studio-add',p,'＋ Eigenen Bereich ergänzen',false,s.blocks.length>=20?'disabled':'')}<label class="workspace-field" for="studio-reflection"><span>${e(cfg.reflection)}</span><textarea id="studio-reflection" data-studio="reflection" data-project="${p.id}" maxlength="3000" rows="3">${e(s.reflection)}</textarea></label>`}</section><section class="content-panel"><h2>Mit Ihrer Fassung weiterarbeiten</h2><div class="export-steps"><div><span class="step-number">1</span><strong>Prüfen</strong><p>Vorschau öffnen. Sind Inhalt, Reihenfolge und Bilder verständlich?</p></div><div><span class="step-number">2</span><strong>Verwenden</strong><p>In OneNote oder PowerPoint einfügen oder über den Druckdialog als PDF speichern.</p></div><div><span class="step-number">3</span><strong>Weiterarbeiten</strong><p>Die JSON-Sicherung enthält auch Ihren Entwurf und die eingefügten Bilder. Später oben mit «Sicherung laden» öffnen.</p></div></div><div class="p-actions">${action('studio-copy',p,'Für OneNote / Word kopieren',true)}${action('studio-print',p,'Als PDF drucken')}${action('studio-html',p,'Ansicht als HTML speichern')}${action('backup',p,'Bearbeitbare Sicherung')}</div><p class="note-hint">In der Ziel-App fügen Sie mit Strg + V ein. Format und Bilder können je nach App anders übernommen werden; prüfen Sie das Ergebnis. Externe Videos und Ihre fertige Scan-PDF speichern Sie zusätzlich in OneDrive.</p></section>`:''}`;
    }
    function handleInput(el,p){if(!el.dataset.studio)return false;const key=el.dataset.studio,index=el.hasAttribute('data-block')?Number(el.dataset.block):null;
      api.change(p,r=>{if(index!==null&&r.studio.blocks[index]&&['title','text','extra','caption'].includes(key))r.studio.blocks[index][key]=el.value;else if(index===null&&['title','intro','reflection'].includes(key))r.studio[key]=el.value;r.startedAt||=new Date().toISOString();});
      if(index!==null&&key==='title'){const label=$('#block-label-'+index);if(label)label.textContent=el.value||'Eigener Abschnitt';}return true;
    }
    function handleChange(el,p){
      if(el.dataset.plan){api.change(p,r=>{r.planner=L.cleanPlanner({...r.planner,[el.dataset.plan]:el.value});if(el.dataset.plan==='readiness')r.planner.session.mandatoryDone=false;});api.render(false);return true;}
      if(el.hasAttribute('data-remaining')){api.change(p,r=>{r.planner.remaining[Number(el.dataset.remaining)]=Math.max(1,Math.min(90,Number(el.value)||1));});api.render(false);return true;}return false;
    }
    function handoff(p){const r=rfor(p),pl=r.planner,s=p.steps.find((_,i)=>!r.checks.includes(i));api.dialog('Gut aufhören. Einfach wieder einsteigen.',`<ol class="handoff-checks"><li>Speichern Sie zuerst Ihr tatsächliches Produkt in OneDrive. Bei einer Web-Vorlage sichern Sie anschliessend auch den Arbeitsstand.</li><li>Prüfen Sie Ihren letzten Zwischenstand. Zeitablauf ersetzt kein Ergebnis-Häkchen.</li><li>Notieren Sie den nächsten kleinen Handgriff und den Speicherort.</li></ol>${field('handoff-file','Wo finde ich meine Arbeit wieder?',pl.file,'maxlength="500" placeholder="Tatsächlicher Ordner und Dateiname oder: Meine Werkbank hier auf der Webseite"')}<label class="workspace-field" for="handoff-next"><span>Was tue ich beim nächsten Mal als Erstes?</span><textarea id="handoff-next" maxlength="1500" rows="3">${e(pl.nextAction||r.notes.pause||(s?s.title:'Qualitätskriterien am Produkt prüfen'))}</textarea></label>${pl.readiness==='open'?field('handoff-mandatory','Geschätzte Pflichtarbeit, die danach noch offen bleibt (Minuten)',pl.mandatory,'min="0" max="180"','number'):''}<p class="note-hint">Bei einem angefangenen Schritt: Beschreiben Sie die genaue Stelle und schätzen Sie im Cockpit vor dem nächsten Start seine Restzeit.</p><div class="p-actions">${action('lesson-finish-backup',p,'Etappe merken und Sicherung herunterladen',true)}${action('lesson-finish',p,'Etappe nur in diesem Browser merken')}</div>`);}
    async function importImage(file,p,index){
      const owner=api.owner();if(!file||!/^image\/(png|jpeg|webp)$/.test(file.type)||file.size>8*1024*1024){api.toast('Bitte wählen Sie ein PNG-, JPG- oder WebP-Bild bis 8 MB.');return;}
      try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Die Bilddatei konnte nicht gelesen werden.'));reader.readAsDataURL(file);});
        const im=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('Dieses Bild lässt sich nicht öffnen.'));img.src=data;});
        if(im.naturalWidth*im.naturalHeight>40000000)throw new Error('Bitte verkleinern Sie das Bild zuerst auf höchstens 40 Megapixel.');
        if(!im.naturalWidth||!im.naturalHeight)throw new Error('Das Bild hat keine lesbare Grösse.');
        let width=im.naturalWidth*Math.min(1,1280/im.naturalWidth,1600/im.naturalHeight),output='';
        for(let attempt=0;attempt<7;attempt++){const canvas=document.createElement('canvas');canvas.width=Math.round(width);canvas.height=Math.max(1,Math.round(im.naturalHeight*width/im.naturalWidth));const ctx=canvas.getContext('2d');if(!ctx)throw new Error('Die Bildverarbeitung wird von diesem Browser nicht unterstützt.');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(im,0,0,canvas.width,canvas.height);output=canvas.toDataURL('image/jpeg',Math.max(.48,.84-attempt*.06));if(output.length<=180000)break;width*=.88;}
        if(!output.startsWith('data:image/jpeg;base64,')||output.length>180000)throw new Error('Das Bild ist noch zu gross. Wählen Sie einen kleineren Ausschnitt.');
        if(api.owner()!==owner||!rfor(p).studio.blocks[index])return;
        const current=rfor(p).studio.blocks[index].image||'';if(JSON.stringify(api.state()).length-current.length+output.length>2200000)throw new Error('Der Bildspeicher für Ihre Projekte ist fast voll. Sichern Sie Ihre Arbeit und entfernen Sie nicht mehr benötigte Bilder. Das Original können Sie in OneDrive behalten.');
        api.change(p,r=>{r.studio.blocks[index].image=output;});api.render(false);api.toast('Bild eingefügt. Prüfen Sie in der Vorschau, ob wichtige Details lesbar geblieben sind.');
      }catch(error){api.toast(error.message||'Das Bild konnte nicht eingefügt werden.');}
    }
    async function handleClick(button,p){const name=button.dataset.action;if(!p)return false;const r=rfor(p),pl=r.planner,index=Number(button.dataset.block);
      switch(name){
        case 'lesson-start':{
          if(pl.readiness==='unset'){api.toast('Wählen Sie zuerst Ihren Stand bei den Pflichtaufträgen aus.');$('#plan-readiness')?.focus();return true;}
          for(const other of projects)if(other.id!==p.id&&rfor(other).planner.session.status==='running')api.change(other,x=>{x.planner.session.elapsed=Math.round(L.elapsed(x.planner));x.planner.session.status='paused';});
          api.change(p,x=>{x.planner.session={status:'running',startedAt:new Date().toISOString(),elapsed:0,mandatoryDone:false,checksAtStart:[...x.checks]};x.startedAt||=new Date().toISOString();});api.render(false);api.toast('Ihr Zeitfenster läuft. Beginnen Sie beim ersten Eintrag im Etappenplan.');return true;}
        case 'lesson-pause':api.change(p,x=>{x.planner.session.elapsed=Math.round(L.elapsed(x.planner));x.planner.session.status='paused';});api.render(false);return true;
        case 'lesson-resume':for(const other of projects)if(other.id!==p.id&&rfor(other).planner.session.status==='running')api.change(other,x=>{x.planner.session.elapsed=Math.round(L.elapsed(x.planner));x.planner.session.status='paused';});api.change(p,x=>{x.planner.session.startedAt=new Date().toISOString();x.planner.session.status='running';});api.render(false);return true;
        case 'mandatory-done':api.change(p,x=>{x.planner.session.mandatoryDone=true;x.planner.readiness='done';});api.render(false);api.toast('Ihr Projektplan verwendet die verbleibende Zeit jetzt für das Projekt.');return true;
        case 'lesson-close':handoff(p);return true;
        case 'lesson-finish':case 'lesson-finish-backup':{
          const file=$('#handoff-file').value,next=$('#handoff-next').value,remaining=pl.readiness==='open'?Number($('#handoff-mandatory').value):null;
          api.change(p,x=>{const minutes=Math.min(x.planner.minutes,Math.round(L.elapsed(x.planner)/60));if(remaining!==null){x.planner.mandatory=Math.max(0,Math.min(180,remaining||0));if(x.planner.mandatory===0)x.planner.readiness='done';}x.planner.file=file.slice(0,500);x.planner.nextAction=next.slice(0,1500);x.notes.pause=next.slice(0,1500);x.planner.history.push({endedAt:new Date().toISOString(),minutes,steps:x.checks.filter(i=>!x.planner.session.checksAtStart.includes(i)).length,note:x.planner.nextAction});x.planner.history=x.planner.history.slice(-12);x.planner.session.status='closed';x.planner.session.elapsed=minutes*60;});$('#projectDialog').close();api.render(false);if(name==='lesson-finish-backup')api.backup();else api.toast('Ihr Wiedereinstieg ist gemerkt. Denken Sie vor einem Gerätewechsel an die Sicherung.');return true;}
        case 'template-preview':{const t=L.setups[p.id].templates.find(t=>t.id===button.dataset.template);if(!t)return true;pendingTemplate={project:p.id,id:t.id,owner:api.owner()};api.dialog(t.name,`<p>${e(t.description)} Sie können alle Titel ändern, eigene Bereiche ergänzen und Bilder einfügen.</p><div class="template-preview"><strong>${e(t.title||'Ihr eigener Titel')}</strong><ol>${t.titles.map(x=>`<li>${e(x)}<span>Platz für Inhalt, Test und eigenes Bild</span></li>`).join('')}</ol></div>${L.hasWork(r.studio)?'<p class="finish-hint"><strong>Sie haben bereits einen Entwurf.</strong> Beim Übernehmen werden die Inhalte der Werkbank dieses Projekts ersetzt. Häkchen, Notizen und die anderen Projekte bleiben erhalten.</p>':''}<div class="p-actions">${L.hasWork(r.studio)?action('backup',p,'Vorhandene Fassung zuerst sichern'):''}${action('template-apply',p,L.hasWork(r.studio)?'Vorhandenen Entwurf durch diese Vorlage ersetzen':'Diese Vorlage verwenden',true)}</div>`);return true;}
        case 'template-apply':if(pendingTemplate?.project===p.id&&pendingTemplate.owner===api.owner()){undoStudio={project:p.id,owner:api.owner(),studio:JSON.parse(JSON.stringify(r.studio))};api.change(p,x=>{x.studio=L.makeTemplate(p,pendingTemplate.id);x.startedAt||=new Date().toISOString();});pendingTemplate=null;preview=false;$('#projectDialog').close();api.render(false);api.toast('Vorlage übernommen. Ergänzen Sie jetzt Ihre eigenen Inhalte.');}return true;
        case 'studio-undo':api.dialog('Vorlagenwechsel rückgängig machen?',`<p>Die Fassung vor dem letzten Vorlagenwechsel wird wiederhergestellt. Seitdem eingegebene Inhalte werden dabei ersetzt.</p><div class="p-actions">${action('backup',p,'Jetzige Fassung zuerst sichern')}${action('studio-undo-confirm',p,'Frühere Fassung wiederherstellen',true)}</div>`);return true;
        case 'studio-undo-confirm':if(undoStudio?.project===p.id&&undoStudio.owner===api.owner()){api.change(p,x=>{x.studio=undoStudio.studio;});undoStudio=null;$('#projectDialog').close();api.render(false);}return true;
        case 'studio-toggle':preview=!preview;api.render(false);return true;
        case 'studio-add':if(r.studio.blocks.length<20)api.change(p,x=>{x.studio.blocks.push({id:'b'+x.studio.blocks.length,title:'Eigener Bereich',text:'',extra:'',image:'',caption:''});});api.render(false);return true;
        case 'studio-up':case 'studio-down':{const target=index+(name==='studio-up'?-1:1);if(target>=0&&target<r.studio.blocks.length)api.change(p,x=>{[x.studio.blocks[index],x.studio.blocks[target]]=[x.studio.blocks[target],x.studio.blocks[index]];});api.render(false);return true;}
        case 'studio-remove':if(r.studio.blocks[index])api.dialog('Diesen Bereich entfernen?',`<p>«${e(r.studio.blocks[index].title)}» mit Text und Bild entfernen?</p><p>Die übrigen Bereiche bleiben erhalten.</p>${action('studio-remove-confirm',p,'Diesen Bereich entfernen',true,`data-block="${index}"`)}`);return true;
        case 'studio-remove-confirm':api.change(p,x=>{x.studio.blocks.splice(index,1);});$('#projectDialog').close();api.render(false);return true;
        case 'studio-image':pendingImage={project:p.id,index,owner:api.owner()};$('#studioImageFile').value='';$('#studioImageFile').click();return true;
        case 'studio-image-remove':api.change(p,x=>{if(x.studio.blocks[index])x.studio.blocks[index].image='';});api.render(false);return true;
        case 'studio-print':$('#printProject').innerHTML=productPreview(p);globalThis.print();return true;
        case 'studio-html':api.download(`${p.id}-Meine-Fassung.html`,`<!doctype html><html lang="de-CH"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${e(r.studio.title||p.title)}</title><style>body{font:18px/1.6 system-ui,sans-serif;color:#18364c;max-width:900px;margin:40px auto;padding:0 24px}h2{font-size:2rem}h3{font-size:1.3rem}p{white-space:pre-wrap;overflow-wrap:anywhere}.product-block{border-top:2px solid #cad9e2;margin:32px 0;padding-top:16px;break-inside:avoid}.product-index{color:#567}.product-evidence{background:#f1f5f8;padding:16px}img{max-width:100%;max-height:600px;object-fit:contain}figcaption{font-size:15px}.eyebrow{font-size:14px;text-transform:uppercase}@media print{body{font-size:11pt;margin:0}.product-block{break-inside:avoid}@page{margin:18mm}}</style>${productPreview(p)}</html>`,'text/html;charset=utf-8');return true;
        case 'studio-copy':{const html=productPreview(p),text=L.studioText(r.studio);try{if(globalThis.ClipboardItem&&navigator.clipboard?.write)await navigator.clipboard.write([new ClipboardItem({'text/html':new Blob([html],{type:'text/html'}),'text/plain':new Blob([text],{type:'text/plain'})})]);else {await navigator.clipboard.writeText(text);api.toast('Text kopiert. Bilder übernimmt dieser Browser nicht mit; fügen Sie sie in der Ziel-App separat ein.');return true;}api.toast('Fassung kopiert. In der Ziel-App mit Strg + V einfügen und das Ergebnis prüfen.');}catch{api.dialog('Manuell kopieren',`<p>Die Zwischenablage ist hier nicht verfügbar. Markieren Sie den Text und kopieren Sie ihn mit Strg + C. Bilder können Sie über die HTML-Ansicht übernehmen.</p><label for="copyStudio">Ihr Entwurf</label><textarea class="template-text" id="copyStudio" readonly>${e(text)}</textarea>`);$('#copyStudio').focus();$('#copyStudio').select();}return true;}
        case 'enlarge-example':{const s=media()[p.id]?.chapters[Number(button.dataset.scene)];if(s)api.dialog(s.title,`<img class="enlarged-example" src="${asset(s.image)}" alt="${e(s.title)}"><p>${e(s.caption)}</p>`,'wide');return true;}
        case 'video-chapter':{const s=media()[p.id]?.chapters[Number(button.dataset.scene)],v=$('#projectVideo');if(s&&v){const seek=()=>{v.currentTime=s.start;v.play()?.catch(()=>api.toast('Starten Sie das Video über die Wiedergabetaste.'));};if(v.readyState>=1)seek();else{v.addEventListener('loadedmetadata',seek,{once:true});v.load();}v.scrollIntoView({block:'center',behavior:'auto'});}return true;}
      }return false;
    }
    function init(){const file=$('#studioImageFile');file?.addEventListener('change',async event=>{const p=projects.find(p=>p.id===pendingImage?.project);if(p&&pendingImage.owner===api.owner())await importImage(event.target.files?.[0],p,pendingImage.index);});document.addEventListener('paste',event=>{const el=event.target,p=projects.find(p=>p.id===el.dataset?.project);if(!p||!el.hasAttribute('data-block'))return;const item=[...(event.clipboardData?.items||[])].find(i=>i.kind==='file'&&/^image\//.test(i.type));if(item){event.preventDefault();importImage(item.getAsFile(),p,Number(el.dataset.block));}});if(typeof setInterval==='function')setInterval(()=>{const route=C.route(location.hash,projects),p=route.project;if(p&&route.page==='planner'&&rfor(p).planner.session.status==='running'){const el=$('#lessonSchedule');if(el&&!el.contains?.(document.activeElement))el.innerHTML=schedule(p);}const mini=$('#liveAssistant');if(p&&mini)mini.innerHTML=summary(p);},30000);}
    return {figure,video,mediaView,summary,plannerView,studioView,productPreview,handleInput,handleChange,handleClick,loadFocus,init,reset:()=>{pendingTemplate=null;pendingImage=null;undoStudio=null;preview=false;},undoButton:p=>undoStudio?.project===p.id&&undoStudio.owner===api.owner()?action('studio-undo',p,'Vorlagenwechsel rückgängig machen'):''};
  };
})();
